import sympy
from sympy import QQ, factor, minpoly, Poly, Mul
from sympy.abc import x

# Top-level setup
from sympy import sqrt, I, pi, Rational

def is_subfield(gens_sub, gens_super):
    """Check if the field generated by gens_sub is a subfield of the field generated by gens_super over Q."""
    if not gens_sub:
        return True
    try:
        if not gens_super:
            # If the superfield is Q, all generators of the subfield must be rational.
            for g in gens_sub:
                QQ.from_expr(g)
            return True
        K_super = QQ.algebraic_field(*gens_super)
        for g in gens_sub:
            K_super.from_expr(g)
        return True
    except Exception:
        return False

def minpoly_over_F(g, F_gens, x):
    """Compute the minimal polynomial of g over the field F generated by F_gens."""
    mp_Q = minpoly(g, x)
    if not F_gens:
        return mp_Q
    try:
        factored = factor(mp_Q, extension=F_gens)
        for fac in factored.as_ordered_factors():
            if fac.has(x):
                val = fac.subs(x, g)
                if sympy.simplify(val) == 0:
                    return fac
    except Exception:
        pass
    return mp_Q

def is_normal_extension(K_gens, F_gens):
    """Check if K/F is a normal extension."""
    if not is_subfield(F_gens, K_gens):
        return False
    try:
        for g in K_gens:
            mp_F = minpoly_over_F(g, F_gens, x)
            factored_K = factor(mp_F, extension=K_gens)
            for fac in factored_K.as_ordered_factors():
                if fac.has(x) and Poly(fac, x).degree() > 1:
                    return False
        return True
    except Exception:
        return False

def conditions(witness):
    """
    Check the hypotheses and negated conclusion for the given witness.
    The witness is expected to be a tuple (F_gens, K_gens, L_gens) representing
    the generators of the fields F, K, and L over Q.
    """
    try:
        F_gens, K_gens, L_gens = witness
    except Exception:
        return [False, False, False]
    
    # H_1: L/F is a field extension
    try:
        h1 = is_subfield(F_gens, L_gens)
    except Exception:
        h1 = False
        
    # H_2: K/F is a normal extension
    try:
        h2 = is_normal_extension(K_gens, F_gens)
    except Exception:
        h2 = False
        
    # ¬Q: The conclusion fails
    # The conclusion assumes that the restriction of an F-automorphism of L to K
    # is a well-defined F-automorphism of K. This fails if K is not a subfield of L.
    try:
        neg_q = not is_subfield(K_gens, L_gens)
    except Exception:
        neg_q = False
        
    return [h1, h2, neg_q]

CONDITION_LABELS = [
    "H_1: L/F is a field extension",
    "H_2: K/F is a normal extension",
    "¬Q: The restriction map is not well-defined (K is not a subfield of L)"
]

N_HYP = 2
NEG_Q_INDEX = 2